let data = $json;

function validateLead(data) {
  const errors = [];

  // --- Skip validation entirely for non-lead emails ---
  if (!data.is_lead_email) {
    return {
      valid: true,
      errors,
      needs_llm_fallback: false,
      data
    };
  }

  // --- Lead ID validation (structural anchor #1) ---
  const hasValidLeadId = typeof data.lead_id === "string" &&
    /^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/i.test(data.lead_id.trim());

  if (!hasValidLeadId) {
    errors.push("Lead ID is missing or malformed");
    data.lead_id = null;
  }

  // --- Phone validation and normalisation (structural anchor #2) ---
  let hasValidPhone = false;

  if (!data.phone || (typeof data.phone === "string" && data.phone.trim() === "")) {
    errors.push("Phone number is required");
    data.phone = null;
  } else {
    let digits = data.phone.replace(/\D/g, ""); // strips the "+" along with any other non-digits

    digits = digits.startsWith("91") && digits.length === 12 ? digits.slice(2) : digits;

    if (digits.length === 10) {
      digits = "91" + digits;
    }

    if (/^91\d{10}$/.test(digits)) {
      hasValidPhone = true;
      data.phone = "+" + digits; // BUG FIX + FORMAT MATCH: normalised digits saved back
                                  // as "+91XXXXXXXXXX", matching your parser's output style
    } else {
      errors.push("Phone must be in +91XXXXXXXXXX format");
      data.phone = null;
    }
  }

  // --- Placeholder email handling ---
  if (data.email) {
    const email = data.email.trim().toLowerCase();

    const placeholderPatterns = [
      /@unknown\.com$/,
      /@noemail\.com$/,
      /^na@na\.com$/,
      /^test@test\.com$/
    ];

    data.email = placeholderPatterns.some(p => p.test(email)) ? null : email;
  }

  // --- Empty strings -> null (name, vehicle_model, followup_datetime, sent_to, raw_subject) ---
  for (const key of Object.keys(data)) {
    if (typeof data[key] === "string" && data[key].trim() === "") {
      data[key] = null;
    }
  }

  // --- Fallback trigger ---
  // Respect whatever parseLeadEmail() already set, OR'd with what we find here.
  const needsLlmFallback = Boolean(data.needs_llm_fallback) || (!hasValidLeadId && !hasValidPhone);
  data.needs_llm_fallback = needsLlmFallback;

  return {
    valid: errors.length === 0,
    errors,
    needs_llm_fallback: needsLlmFallback,
    data
  };
}

let results = validateLead(data);

return results;

