function formatConversation(messages) {
  if (!Array.isArray(messages) || messages.length === 0) {
    return "";
  }

  const transcript = [];

  for (const item of messages) {
    let item_json = item.json;
    const message = item_json?.message ?? {};
    const role = message.type;
    let content = message.content ?? "";

    if (role === "human") {
      transcript.push(`Human: ${content}`);
    } else if (role === "ai") {
      // AI responses are stored as a JSON string
      try {
        const parsed = JSON.parse(content);

        if (parsed?.output?.reply) {
          content = parsed.output.reply;
        }
      } catch (_) {
        // Ignore parsing errors and use raw content
      }

      transcript.push(`AI: ${content}`);
    }
  }
  console.log(transcript);
  return transcript.join("\n\n");
}

let input = $input.all();

const messages = {
  data: input
}


let message = formatConversation(messages.data);

//console.log(message);

return {
  "message":message
};
